pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(address funder, uint256 amount, address withdrawer) public {
        vm.assume(funder != address(0));
        vm.assume(withdrawer != address(0));
        amount = bound(amount, 0, address(this).balance / 2 + 1 ether);

        // funder (anyone, including a non-owner) tops up c through the payable fallback
        vm.deal(funder, amount + 1);
        vm.prank(funder);
        (bool okFund, ) = address(c).call{value: amount}("");
        assertTrue(okFund, "fallback deposit should succeed");

        uint256 balanceBefore = address(c).balance;

        // an arbitrary (possibly non-owner) party attempts to drain the contract
        vm.prank(withdrawer);
        bool ok;
        try c.withdrawAll() { ok = true; } catch { ok = false; }

        // GENERAL RULE: withdrawAll succeeds ONLY for the owner; a non-owner's
        // attempt must revert and leave the contract's balance untouched.
        assertTrue(
            (ok == (withdrawer == c.owner())) &&
            (!ok || withdrawer == c.owner() ? true : address(c).balance == balanceBefore),
            "non-owner must not be able to drain c via withdrawAll"
        );
    }
}

