pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(uint128 amount, address actor) public {
        // actor must be the owner (deployer) for onlyOwner to pass; keep amount admissible
        vm.assume(actor != address(0));
        vm.prank(actor);
        // c was deployed by this test contract, so owner == address(this); require actor is owner
        vm.assume(actor == address(this));

        // fund the contract so the internal call carries `amount`
        vm.deal(address(c), uint256(amount) + 1);

        uint256 before = c.depositsCount();
        vm.prank(actor);
        // target is the contract itself: P routes value to _target's payable fallback,
        // which increments depositsCount. M pays msg.sender instead, so the fallback never runs.
        (bool ok, ) = address(c).call{value: 0}(
            abi.encodeWithSelector(c.sendMoney.selector, address(c), uint256(amount))
        );

        assertTrue(ok && c.depositsCount() == before + 1);
    }
}

