import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(uint256 amount) public {
        // WIDE domain: any amount is admissible, including 0.
        amount = bound(amount, 0, type(uint256).max / 2);

        address owner = address(this);

        // optionally fund the contract through the public fallback
        if (amount > 0) {
            vm.deal(owner, amount);
            vm.prank(owner);
            address(c).call{value: amount}("");
        }

        // The owner's withdrawAll must always complete successfully:
        // in P it transfers exactly address(c).balance (0 is a valid transfer
        // to an EOA owner); in M it transfers 1 wei and reverts whenever the
        // balance is 0 (amount == 0).
        bool ok;
        vm.prank(owner);
        try c.withdrawAll() { ok = true; } catch { ok = false; }

        assertTrue(ok);
    }
}

